-- ================================================================
-- DELETE ALL COMPLETED LOAN REPAYMENTS & RE-INSERT CORRECTLY
-- ================================================================
DELETE FROM loan_service.loan_repayments
WHERE loan_id IN (
    SELECT loan_id FROM loan_service.loans
    WHERE tenant_id = 1 AND status = 'COMPLETED'
);

